fn zone() -> Zone {
    Zone {
        id: 1,
        name: "example.net".into(),
        serial: 7,
        soa_mname: "NS1.Example.net.".into(),
        soa_rname: "Hostmaster.EXAMPLE.net.".into(),
        refresh: 3600,
        retry: 600,
        expire: 1209600,
        minimum: 300,
        default_ttl: 3600,
        created_at: String::new(),
        updated_at: String::new(),
        owner_id: None,
        dnssec: false,
        signed_at: None,
        overrides: None,
        record_policy: None,
        nsec3: false,
        secondary: None,
        settings: None,
    }
}

fn stored(t: &str, value: &str, ttl: u32) -> Stored {
    Stored {
        id: 1,
        zone_id: 1,
        name: "x".into(),
        rtype: Rt::parse(t).unwrap(),
        value: value.into(),
        ttl: Some(ttl),
        created_at: String::new(),
        updated_at: String::new(),
        expires_at: None,
    }
}

/// The RRset as this server serves it.
fn served(owner: &Name, ttl: u32, t: &str, values: &[&str]) -> Vec<Record> {
    match t {
        "SOA" => {
            let c = Catalog::build(vec![zone()], vec![]);
            vec![soa_record(c.zones.get("example.net.").unwrap(), ttl).unwrap()]
        }
        "NSEC" => {
            let mut parts = values[0].split_whitespace();
            let next = Name::from_ascii(parts.next().unwrap()).unwrap();
            let types: Vec<u16> = parts
                .map(|p| u16::from(p.parse::<hickory_proto::rr::RecordType>().unwrap()))
                .collect();
            vec![wire::raw_record(
                owner.clone(),
                ttl,
                wire::T_NSEC,
                wire::nsec_rdata(&next, &types),
            )]
        }
        "TXT" => {
            // Presentation "a..." "b..." -> the stored raw text (split again on serving).
            let raw: String = values[0].split('"').skip(1).step_by(2).collect();
            vec![to_rr(&zone(), &stored(t, &raw, ttl), owner).unwrap()]
        }
        _ => values
            .iter()
            .map(|v| to_rr(&zone(), &stored(t, v, ttl), owner).unwrap())
            .collect(),
    }
}

fn key() -> (ReplDnssecKey, KeyInfo) {
    use ring::signature::{EcdsaKeyPair, KeyPair, ECDSA_P256_SHA256_FIXED_SIGNING};
    let pk8 = data_encoding::BASE64.decode(PKCS8.as_bytes()).unwrap();
    let pair = EcdsaKeyPair::from_pkcs8(
        &ECDSA_P256_SHA256_FIXED_SIGNING,
        &pk8,
        &ring::rand::SystemRandom::new(),
    )
    .unwrap();
    let public = pair.public_key().as_ref()[1..].to_vec();
    let stored = ReplDnssecKey {
        zone_id: 1,
        zone: "example.net".into(),
        algorithm: 13,
        flags: 257,
        key_tag: wire::key_tag(&wire::dnskey_rdata(257, 13, &public)),
        public_key: data_encoding::BASE64.encode(&public),
        private_key: Hidden(PKCS8.into()),
        created_at: String::new(),
        rollover: None,
    };
    let info = KeyInfo::from_stored(&stored).unwrap();
    (stored, info)
}

#[test]
fn dnskey_key_tag_and_ds_match_dnspython_and_bind() {
    let (stored, info) = key();
    assert_eq!(info.key_tag, KEY_TAG, "key tag as dnspython computes it");
    assert_eq!(stored.key_tag, KEY_TAG);
    let text = info.dnskey_text("example.net.", 3600);
    assert_eq!(
        text.split_whitespace().skip(4).collect::<Vec<_>>().join(""),
        DNSKEY.replace(' ', ""),
        "DNSKEY RDATA as dnspython prints it"
    );
    for (dt, bind) in [(2u8, BIND_DS[0]), (4, BIND_DS[1])] {
        let d = info.ds("example.net.", dt).unwrap();
        let ours = format!(
            "example.net. IN DS {}",
            wire::ds_text(info.key_tag, 13, dt, &d)
        );
        assert_eq!(ours, bind, "DS digest type {dt} equals dnssec-dsfromkey");
    }
    ZoneKey::load(&stored).expect("the fixed key loads");
}

#[test]
fn canonical_form_matches_dnspython_and_its_signatures_verify() {
    let (_, info) = key();
    let apex = Name::from_ascii("example.net.").unwrap();
    for (owner, ttl, t, values, data_hex, rrsig_hex) in CASES {
        let owner_n = Name::from_ascii(owner).unwrap();
        let set = served(&owner_n, *ttl, t, values);
        let rrsig = hex::decode(rrsig_hex).unwrap();
        let (fields, _) = parse_rrsig(&rrsig).unwrap();
        let rdatas: Vec<Vec<u8>> = set
            .iter()
            .map(|r| wire::canonical_rdata(&r.data).unwrap())
            .collect();
        let data = signed_data(&fields, &owner_n, &rdatas);
        assert_eq!(
            hex::encode(&data),
            *data_hex,
            "{owner} {t}: canonical signed data differs from dnspython's"
        );
        // dnspython's signature verifies against the served RRset.
        let sig = wire::raw_record(owner_n.clone(), *ttl, wire::T_RRSIG, rrsig.clone());
        let refs: Vec<&Record> = set.iter().collect();
        verify_rrset(&refs, &sig, &apex, &info, fields.inception + 1)
            .unwrap_or_else(|e| panic!("{owner} {t}: {e}"));
    }
}

#[test]
fn wildcard_expansion_verifies_with_the_wildcard_signature() {
    let (_, info) = key();
    let apex = Name::from_ascii("example.net.").unwrap();
    let (_, ttl, t, values, _, rrsig_hex) =
        CASES.iter().find(|c| c.0 == "*.gate.example.net.").unwrap();
    // Served under the query name; the RRSIG labels (3) rebuild "*.gate.example.net.".
    let qname = Name::from_ascii("Foo.Bar.gate.example.net.").unwrap();
    let set = served(&qname, *ttl, t, values);
    let rrsig = hex::decode(rrsig_hex).unwrap();
    let sig = wire::raw_record(qname.clone(), *ttl, wire::T_RRSIG, rrsig.clone());
    let (fields, _) = parse_rrsig(&rrsig).unwrap();
    let refs: Vec<&Record> = set.iter().collect();
    verify_rrset(&refs, &sig, &apex, &info, fields.inception + 1).unwrap();
    // A tampered record does not verify.
    let mut bad = set.clone();
    bad[0].data = hickory_proto::rr::RData::A(hickory_proto::rr::rdata::A([192, 0, 2, 4].into()));
    let refs: Vec<&Record> = bad.iter().collect();
    assert!(verify_rrset(&refs, &sig, &apex, &info, fields.inception + 1).is_err());
}

/// O25: the Ed25519 examples of RFC 8080 §6.1 (the first key: DNSKEY,
/// DS digest type 2, and the RRSIG over `example.com. 3600 IN MX 10
/// mail.example.com.`). Ed25519 signatures are deterministic, so the
/// signature made here equals the RFC's byte for byte.
#[test]
fn ed25519_matches_rfc8080_examples() {
    use super::ED25519_ALGORITHM as ALG;
    // PKCS#8 v1 (RFC 8410) around the RFC's private key (32-byte seed).
    let seed = data_encoding::BASE64
        .decode(b"ODIyNjAzODQ2MjgwODAxMjI2NDUxOTAyMDQxNDIyNjI=")
        .unwrap();
    let mut pkcs8 = hex::decode("302e020100300506032b657004220420").unwrap();
    pkcs8.extend(&seed);
    let public = "l02Woi0iS8Aa25FQkUd9RMzZHJpBoRQwAQEX1SxZJA4=";
    let pk = data_encoding::BASE64.decode(public.as_bytes()).unwrap();
    let stored = ReplDnssecKey {
        zone_id: 1,
        zone: "example.com".into(),
        algorithm: ALG,
        flags: 257,
        key_tag: wire::key_tag(&wire::dnskey_rdata(257, ALG, &pk)),
        public_key: public.into(),
        private_key: Hidden(data_encoding::BASE64.encode(&pkcs8)),
        created_at: String::new(),
        rollover: None,
    };
    assert_eq!(stored.key_tag, 3613, "key tag of the RFC's DNSKEY");
    let zk = ZoneKey::load(&stored).expect("the RFC's key loads; public key matches");
    let info = KeyInfo::from_stored(&stored).unwrap();
    assert_eq!(
        hex::encode(info.ds("example.com.", 2).unwrap()),
        "3aa5ab37efce57f737fc1627013fee07bdf241bd10f3b1964ab55c78e79a304b",
        "DS 3613 15 2 of the RFC"
    );
    let owner = Name::from_ascii("example.com.").unwrap();
    let mx = hickory_proto::rr::RData::MX(hickory_proto::rr::rdata::MX::new(
        10,
        Name::from_ascii("mail.example.com.").unwrap(),
    ));
    let rr = Record::from_rdata(owner.clone(), 3600, mx);
    let fields = wire::RrsigFields {
        type_covered: 15,
        algorithm: ALG,
        labels: 2,
        original_ttl: 3600,
        expiration: 1440021600,
        inception: 1438207200,
        key_tag: 3613,
        signer: owner.clone(),
    };
    let data = signed_data(&fields, &owner, &[wire::canonical_rdata(&rr.data).unwrap()]);
    let sig = zk.sign(&data).unwrap();
    assert_eq!(
        data_encoding::BASE64.encode(&sig),
        "oL9krJun7xfBOIWcGHi7mag5/hdZrKWw15jPGrHpjQeRAvTdszaPD+QLs3fx8A4M3e23mRZ9VrbpMngwcrqNAg==",
        "RRSIG signature of RFC 8080 §6.1"
    );
    let rrsig = wire::raw_record(owner.clone(), 3600, wire::T_RRSIG, fields.rdata(&sig));
    verify_rrset(&[&rr], &rrsig, &owner, &info, 1438207200 + 1).unwrap();
    let mut other = sig.clone();
    other[0] ^= 1;
    assert!(!super::verify(ALG, &pk, &data, &other));
}
